sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    /*
    This script will insert a record in HSBC Email Logs
    when there is an update on the HSBC Qtrack Email Outbounds MSSOTIQUBE-193
    */
    try {

        var initialbody = current.body.getDisplayValue();
        //var body = JSON.stringify(initialbody).slice(1, -1);
        if (current.recipients != '' && current.subject != '' && initialbody != '') {
            var qtse = new GlideRecord('x_hsb11_hsbcmss_qw_hsbc_qtrack_email_outbound');
            qtse.initialize();
            qtse.servicenow_task_id = current.trade_case_task_number;
            qtse.to = current.recipients; 
            qtse.cc = current.copied;
            qtse.from = current.from;
            qtse.bcc = current.blind_copied; 
            qtse.email_subject = current.subject;
            //qtse.email_body = body;
			qtse.email_body = initialbody;
            qtse.classification = "Restricted";
            qtse.state = 'Ready to be sent';
            qtse.insert();
            //gr.from = current.from;
            //gr.bcc = current.blind_copied;
        }
    } catch (err) {
        gs.info("Error captured from business rule - HSBC-Record Creation in Qtrack Outbound " + err);
    }


})(current, previous);
